SELECT analytics_order_facts.payment_method, SUM(analytics_order_facts.net_revenue) / CAST(NULLIF(COUNT(DISTINCT analytics_order_facts.order_id), 0) AS DECIMAL) AS average_order_value FROM analytics_order_facts WHERE analytics_order_facts.year = 2026 AND analytics_order_facts.month = 7 AND analytics_order_facts.region = 'South' AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'enterprise' GROUP BY analytics_order_facts.payment_method ORDER BY average_order_value DESC, analytics_order_facts.payment_method ASC LIMIT 12
